#!/usr/bin/env python3
# luxarch:no-new-follow-ups hook v2 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""An agent fixes what it finds; it does not file it for later.

PreToolUse(mcp__luxpm__luxpm_create_issue, mcp__luxpm__luxpm_update_issue, mcp__luxpm__luxpm_chat,
mcp__luxpm__luxpm_code_to_issues, mcp__luxpm__luxpm_update_checklist): an agent files no issue
for later, in its own repo's LuxPM project or any other, in any session. A bug, a red, a limit or
a follow-up found in the work at hand is fixed in that change. A new issue for it carried the work forward
instead, and the owner's backlog grew by two for every one closed. Onboarding captures and audit
findings are worked in their own run too, or asked of the owner as one question.

A `luxpm_create_issue` passes as an escalation, as work started now, or as a handoff (below). An
escalation takes one of two shapes (this repo's project is the `project:` line of its committed
`.luxpm-receipt`; `project` compares case-insensitively):

- an escalation to another repo's guard: the title is, whole, `[<guard> ESCALATION] <what>`, or
  `[<guard>/<guard> ESCALATION] <what>` for one defect in several guards, naming only guards
  (luxarch, luxlint, luxaudit, luxios) that are not this repo's own project, the labels hold
  `fleet-escalation`, `project` is absent or this repo's project (an escalation is filed in
  the escalating repo's own project, `/escalate`), and the description carries `/escalate`'s
  **Verify** block: the word, then within a few lines the command that shows the guard's defect
  (`--rule`, `--path`, a `make` target, `docker run`, `pytest`, or a guard run with options);
- in a guard's own project (LUXARCH, LUXLINT, LUXAUDIT, LUXIOS), an escalation relayed from
  another project: the title is, whole, `[<KEY>] <what>` for an issue key of that project, the
  labels hold `escalation-from-<project>` naming the same project, which is not this one,
  `project` is absent or this repo's project, and `<KEY>` is a key the owner typed in this
  session (the owner relays an airgapped repo's escalation; `fleet-start-gate` records the keys
  in each prompt the owner types).

A create of work the agent starts now passes: `project` naming this repo's project, a `title`
(no `text`, which LuxPM parses into any title), state `in_progress`, no `waiting_on`, no
escalation or `[<KEY>]` title, and no escalation, `agent:` or `owner-order` label (those have
their own routes, or are the owner's). This is how work no open issue covers is filed: a pin
bump `guard-version-check` reports, the owner's order in chat or a `/fleet-start <note>`, from
the main checkout or mid-issue. The agent files it itself and starts; it never asks the owner
to file it. Its checklist is added from its own worktree. An `in_progress` issue is not set
aside quietly: `no-self-park` refuses moving it to `todo` or `backlog` and parks it only on a
question to the owner, which the owner answers; every `/fleet-start` lists it first. A create in
`backlog`, `todo` or `on_hold`, or one with a later label or a deferral slot (`Follow-up:`)
opening its title or an unquoted description line, is work set aside, and is denied; the denial
names what matched.

Another create passes in a repo with more than one agent: a handoff to another of its agents, in
this repo's project, labelled `agent:<their role>` (one such label), state `todo`, `waiting_on:
"<their role> agent: <the step>"`, where their role and this session's own (the role in the name
the owner gave it, `[<repo> <role>]`) are both declared in the committed `.luxarch.toml`
(`[agents] roles`, read from the main checkout at HEAD) and differ. A session with no name, or a
role the repo does not declare, hands nothing off.

Every other create is denied, `luxpm_code_to_issues` (an issue per TODO in the code) among them.
An update that moves an issue out of `done` or `cancelled` (LuxPM, read when the hook judges
it, shows it closed) is a create too, and is denied, and so is one that retitles an issue that
is not an escalation into an escalation's form, and one that rewrites the
`description` of an issue that is neither this worktree's own issue nor an escalation: work
written into another issue is a follow-up filed there. `luxpm_chat` turns natural language
into any change, so it is denied outright: read with `luxpm_list_issues`, `luxpm_get_context` or
`luxpm_semantic_search`, change with `luxpm_update_issue`. A new item on an issue's checklist
(`luxpm_update_checklist` with an entry that names no existing `item`), or a rewrite of an
existing one (an entry carrying anything but `item` and `done`), passes only on this worktree's
own issue (branch `worktree-<KEY>`), never from the main checkout. Ticking an item passes anywhere.

When the finding is the owner's call (scope, money, a delete), ask the owner one question. The
rule's home: FLEET-AGENT-CONDUCT-STANDARD, "Work what you find; never defer it". An event it cannot
read names no create, and passes, as every process gate does.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _ledger import (
    CLOSED_STATES,
    GUARDS,
    HANDOFF_LABEL,
    LuxPMUnread,
    agent_name,
    agent_role,
    declared_roles,
    handoff_to,
    is_escalation,
    luxpm_issues,
    own_issue_key,
    owner_keys,
    owner_notes,
    read_event,
    repo_project,
    role_name,
    row_labels,
    tree_dir,
)

_CREATE = "mcp__luxpm__luxpm_create_issue"
_UPDATE = "mcp__luxpm__luxpm_update_issue"
_CHAT = "mcp__luxpm__luxpm_chat"
_CODE_TO_ISSUES = "mcp__luxpm__luxpm_code_to_issues"
_CHECKLIST = "mcp__luxpm__luxpm_update_checklist"
_ESCALATION = "fleet-escalation"
_GUARD_NAME = r"(?:luxarch|luxlint|luxaudit|luxios)"
_ESCALATION_TITLE = re.compile(
    rf"\[(?P<guards>{_GUARD_NAME}(?:/{_GUARD_NAME})*) ESCALATION\] \S.*"
)
# `/escalate`'s Verify block: the label, then the command that shows the guard's defect (a guard
# run, a make target or the one failing test) on a line of its own or in code
_VERIFY = re.compile(
    r"\bVerify\b[^\n]*(?:\n[^\n]*){0,6}?(?:--rule\b|--path\b|\bmake [a-z]|\bdocker run\b|"
    r"\bpytest\b|\bluxarch\b[^\n]*--|\bluxlint\b[^\n]*--|\bluxaudit\b[^\n]*--)",
    re.IGNORECASE,
)
_RELAYED = "escalation-from-"
_RELAYED_TITLE = re.compile(r"\[(?P<key>([A-Z][A-Z0-9]+)-\d+)\] \S.*")
_GUARD_PROJECTS = tuple(g.upper() for g in GUARDS)


def _labels(raw: object) -> list[str]:
    if isinstance(raw, str):
        return [s.strip().lower() for s in raw.split(",") if s.strip()]
    if isinstance(raw, list):
        return [str(s).strip().lower() for s in raw]
    return []


def _handoff(inp: dict[str, object], own: str, transcript: str) -> bool:
    """The create hands work to another agent of this repo: in this repo's project, labelled
    `agent:<their role>` (one such label), state todo, `waiting_on: "<their role> agent: <step>"`,
    their role and this session's own both declared in `[agents] roles`, and different."""
    if not own or str(inp.get("project") or "").strip().upper() not in ("", own):
        return False
    labels = _labels(inp.get("labels"))
    if any(
        x in ("fleet-escalation", "escalation", "owner-order")
        or x.startswith("escalation-from-")
        for x in labels
    ):
        return False  # a handoff is no escalation and no owner order
    tags = [x for x in labels if x.startswith(HANDOFF_LABEL)]
    if len(tags) != 1 or str(inp.get("state") or "").strip().lower() != "todo":
        return False
    role = handoff_to(
        inp.get("waiting_on"), agent_role(agent_name(transcript)), declared_roles()
    )
    return bool(role) and HANDOFF_LABEL + role_name(tags[0][len(HANDOFF_LABEL) :]) == (
        f"{HANDOFF_LABEL}{role}"
    )


_OTHER_ROUTE_LABELS = ("fleet-escalation", "escalation", "owner-order")


# A deferral slot: a label that sets work aside, opening the title or an unquoted line of the
# description once its markdown is off ("Follow-up: the retry", "## Later — the importer",
# "1. Not built yet: x"), or standing alone as a lead-in over the lines below it ("## Follow-ups").
# A word in running text ("Fix the TODO parser", "Burn down the reds"), a quoted line, and the
# owner's own recorded /fleet-start note are no slot.
_SLOT_LABEL = (
    r"(?P<slot>later|someday|follow[- ]?ups?|nice[- ]to[- ]have|deferred|not\s+built|"
    r"stated\s+limits?|todo|tbd|parked|left\s+for\s+\S+|out[\s-]+of[\s-]+scope|"
    r"audit[- ]findings?)"
)
_SLOT_QUALIFIER = r"(?:\s+(?:yet|here|for\s+\S+|from\s+\S+|on\s+\S+)|\s*\([^()]*\))*"
_LATER_SLOT = re.compile(
    rf"{_SLOT_LABEL}{_SLOT_QUALIFIER}\s*(?::|[\u2014\u2013]|-\s)", re.IGNORECASE
)
_LATER_LEAD_IN = re.compile(rf"{_SLOT_LABEL}{_SLOT_QUALIFIER}\s*:?\s*", re.IGNORECASE)
_BULLET = re.compile(r"^\s*(?:[-*+\u2022]|\d+[.)])\s+")
_MARKUP_LEAD = re.compile(r"^(?:\s*(?:#{1,6}|>|\|)\s*)+|^[^\w(\[`'\"]+")


def _plain(text: str) -> str:
    """The line with its markdown taken off (as luxpm-close-tracks-deferrals reads a slot): a
    heading's `#`, a table's `|`, a bullet or number, bold and italic marks, leading symbols."""
    t = _BULLET.sub("", text.replace("*", "")).strip().strip("_").strip()
    for _ in range(3):
        t = _MARKUP_LEAD.sub("", _BULLET.sub("", t)).strip()
    return t.strip("_").strip()


def _slot(line: str) -> str | None:
    """The deferral label this line opens with, or None."""
    plain = _plain(line)
    m = _LATER_SLOT.match(plain) or _LATER_LEAD_IN.fullmatch(plain)
    return m.group("slot") if m else None


def _without_notes(text: str) -> str:
    """The text with the owner's recorded /fleet-start notes taken out: the owner's words."""
    for note in sorted(
        (n["note"] for n in owner_notes() if n["note"].strip()), key=len, reverse=True
    ):
        text = text.replace(note, " ")
    return text


# labels that file work for later or as a finding (`agent:`, escalation and owner-order labels
# are judged as other routes)
_LATER_LABELS = frozenset(
    {
        "later",
        "someday",
        "follow-up",
        "follow-ups",
        "followup",
        "nice-to-have",
        "deferred",
        "stated-limit",
        "audit-finding",
    }
)
_ESCALATION_FORM = re.compile(r"\[[^\]\n]{0,60}\bESCALATION\]", re.IGNORECASE)


def _escalation_form(title: str, project: str) -> bool:
    """`[<guard> ESCALATION] …` in any case, or a `[<KEY>] …` title, which every hook reads as a
    relayed escalation (`is_escalation`) in any project."""
    t = title.strip()
    return bool(_ESCALATION_FORM.search(t)) or is_escalation(t, [])


def _started_shape(inp: dict[str, object], own: str) -> str | None:
    """None when the create is work started now; else what in it is not, named for the agent.
    Work started now names this repo's project, is `in_progress`, has a title and nothing of
    another route or of later: no `text`, waiting_on or checklist, no escalation or relay title,
    no escalation, `agent:` or owner-order label, no later label, and no deferral slot opening
    the title or an unquoted description line."""
    if not own:
        return "This checkout's committed .luxpm-receipt names no project."
    project = str(inp.get("project") or "").strip().upper()
    if project != own:
        return f"It names project {project or '(none)'}: file work started now with project={own!r}."
    state = str(inp.get("state") or "backlog").strip().lower()
    if state != "in_progress":
        return f"Its state is {state}: that is work set aside for later."
    title = str(inp.get("title") or "").strip()
    if not title or str(inp.get("text") or "").strip():
        return "It carries `text`, not a `title`: LuxPM parses `text` into any title."
    if str(inp.get("waiting_on") or "").strip():
        return "It carries a waiting_on: work started now waits on no one."
    if inp.get("checklist"):
        return (
            "It carries a checklist: add the checklist from the issue's own worktree."
        )
    labels = _labels(inp.get("labels"))
    if _escalation_form(title, own) or any(
        x in _OTHER_ROUTE_LABELS or x.startswith((_RELAYED, HANDOFF_LABEL))
        for x in labels
    ):
        return (
            "It carries an escalation or relay title, or an escalation, agent: or owner-order "
            "label: those take their own route."
        )
    later = sorted(set(labels) & _LATER_LABELS)
    if later:
        return f"Its label {later[0]!r} files the work for later."
    slot = _slot(_without_notes(title))
    if slot:
        return f"Its title opens with the deferral slot {slot!r}."
    for line in _without_notes(str(inp.get("description") or "")).splitlines():
        if line.lstrip().startswith((">", '"', "\u201c")):
            continue  # a quoted owner note says what the owner said, not what is set aside
        if _slot(line):
            return (
                f"Its description line {line.strip()[:80]!r} is a deferral slot. Quote the "
                "owner's words on `> ` lines; work set aside is no part of work started now."
            )
    return None


def _started_now(inp: dict[str, object], own: str) -> tuple[bool, str]:
    """(passes, why not): the create is work the agent starts at once."""
    why = _started_shape(inp, own)
    return why is None, why or ""


def _escalation(inp: dict[str, object], own: str) -> bool:
    """The create is one of the two escalation shapes."""
    if not own:
        return False
    title = str(inp.get("title") or "")
    labels = _labels(inp.get("labels"))
    project = str(inp.get("project") or "").strip().upper()
    m = _ESCALATION_TITLE.fullmatch(title)
    if (
        m
        and _ESCALATION in labels
        and own not in m.group("guards").upper().split("/")
        and project in ("", own)
        and _VERIFY.search(str(inp.get("description") or ""))
    ):
        return True
    m = _RELAYED_TITLE.fullmatch(title)
    if not m or own not in _GUARD_PROJECTS or project not in ("", own):
        return False
    source = m.group(2).lower()
    return (
        source != own.lower()
        and f"{_RELAYED}{source}" in labels
        and m.group("key") in owner_keys()
    )


_ROUTES = (
    "Work you start now that no open issue covers (a pin bump, the owner's order) you file\n"
    "yourself, in this repo's project, with a title and state in_progress, then work it in its\n"
    "worktree: never ask the owner to file it. The only other routes:\n"
    "  - the defect is in another repo's guard or emitted asset (luxarch, luxlint, luxaudit,\n"
    "    luxios): /escalate it, filed in this repo's own project (title `[<guard> ESCALATION]\n"
    "    <what>`, label fleet-escalation);\n"
    "  - it is the owner's call (scope, money, a delete): ask the owner one question.\n"
    "In a guard's own project, an escalation relayed from another project is filed as\n"
    "`[<KEY>] <what>` with label escalation-from-<that project>.\n"
    "FLEET-AGENT-CONDUCT-STANDARD, 'Work what you find; never defer it'."
)


def _deny(what: str, why: str = "") -> int:
    print(
        "DENIED: this create sets work aside for later; fix what you found in this change instead.\n"
        f"{what}\n"
        + (f"{why}\n" if why else "")
        + "A finding in the work at hand is worked now, with its test seen failing then passing. It\n"
        "is never parked as a new issue, in this project or a sibling's, and never closed as\n"
        "dropped. " + _ROUTES,
        file=sys.stderr,
    )
    return 2


def _key(entry: dict[str, object], project: object) -> str:
    seq = str(entry.get("sequence_id") or "").strip().upper()
    if "-" in seq or not seq:
        return seq
    proj = str(entry.get("project") or project or "").strip().upper()
    return f"{proj}-{seq}" if proj else seq


def _update_faults(inp: dict[str, object]) -> list[str]:
    """Each issue the update moves out of done or cancelled (`KEY (done -> todo)`), each title it
    changes into an escalation's form on an issue that is not one, and each description it rewrites on an issue
    that is neither this worktree's own nor an escalation: work written into another issue is a
    follow-up filed there."""
    entries = [inp]
    updates = inp.get("updates")
    if isinstance(updates, list):
        entries += [u for u in updates if isinstance(u, dict)]
    rewrites = [e for e in entries if e.get("description") not in (None, "")]
    renames = [
        e
        for e in entries
        if _escalation_form(
            str(e.get("title") or ""),
            _key(e, inp.get("project")).partition("-")[0],
        )
    ]
    if not rewrites and not renames and not any(e.get("state") for e in entries):
        return []
    keys = [
        _key(e, inp.get("project"))
        for e in entries
        if e.get("state") or e in rewrites or e in renames
    ]
    try:
        rows = luxpm_issues([k for k in keys if "-" in k])
    except LuxPMUnread as exc:
        return [
            f"LuxPM could not be read ({exc}), and whether {', '.join(keys)} is closed, or is "
            "this worktree's issue or an escalation, decides this change; retry once it answers."
        ]
    own = own_issue_key(tree_dir()).upper()
    out: list[str] = []
    for e in entries:
        key = _key(e, inp.get("project"))
        state = str(e.get("state") or "").strip().lower()
        row = rows.get(key)
        was = str(row.get("state")) if row else ""
        if state and was in CLOSED_STATES and state != was:
            out.append(
                f"You are about to reopen {key} ({was} -> {state}): it is a create."
            )
        if e in renames and row is None:
            out.append(
                f"You are about to retitle {key or 'an issue'} into an escalation's form, and LuxPM "
                "shows no such issue to judge: name it <PROJECT>-<n>."
            )
        if e in renames and row is not None:
            old = str(row.get("title") or "")
            if not _escalation_form(old, key.partition("-")[0]) and not any(
                x in ("fleet-escalation", "escalation") or x.startswith(_RELAYED)
                for x in row_labels(row)
            ):
                out.append(
                    f"You are about to retitle {key} into an escalation's form: an escalation "
                    "is filed as one, with its label and Verify block (/escalate)."
                )
        if (
            e in rewrites
            and key != own
            and row is not None
            and not is_escalation(row.get("title"), row_labels(row))
        ):
            out.append(
                f"You are about to rewrite {key}'s description, which is not this worktree's "
                f"issue ({own or 'none: this is the main checkout'}): work written into another "
                "issue is a follow-up filed there."
            )
    return out


_TICK = frozenset({"item", "done"})


def _checklist(inp: dict[str, object]) -> int:
    """A new item, or a rewrite of an existing one, only on this worktree's own issue; ticking an
    existing item done or not done passes on any issue."""
    items = inp.get("items")
    entries = [
        i for i in (items if isinstance(items, list) else []) if isinstance(i, dict)
    ]
    new = [i for i in entries if i.get("item") in (None, "")]
    rewritten = [
        i for i in entries if i.get("item") not in (None, "") and not set(i) <= _TICK
    ]
    if not new and not rewritten:
        return 0
    seq = str(inp.get("sequence_id") or "").strip().upper()
    if seq and "-" not in seq:
        seq = f"{str(inp.get('project') or '').strip().upper()}-{seq}"
    own = own_issue_key(tree_dir()).upper()
    if own and seq == own:
        return 0
    titles = ", ".join(
        repr(str(i.get("title") or i.get("item") or "")[:60]) for i in new + rewritten
    )
    where = (
        f"this worktree's own issue is {own}"
        if own
        else "this is the main checkout, which works no issue of its own"
    )
    return _deny(
        f"A new or rewritten checklist item on {seq or 'an issue'} ({titles}) carries work "
        "forward.",
        f"New items and rewrites go only on the issue this worktree works; {where}. Ticking an\n"
        "existing item (`item` and `done` only) passes on any issue.",
    )


def main() -> int:
    ev = read_event()
    name = str(ev.get("tool_name") or "")
    ti = ev.get("tool_input")
    inp: dict[str, object] = ti if isinstance(ti, dict) else {}
    if name not in (_CREATE, _UPDATE, _CHAT, _CODE_TO_ISSUES, _CHECKLIST):
        return 0  # an event it cannot read names no create: a process gate passes it
    if name == _CODE_TO_ISSUES:
        return _deny(
            "luxpm_code_to_issues files an issue per TODO in the code: each is a follow-up."
        )
    if name == _CHECKLIST:
        return _checklist(inp)
    if name == _CHAT:
        return _deny(
            "luxpm_chat turns words into any change, so it is not used.",
            "Read with luxpm_list_issues, luxpm_get_context or luxpm_semantic_search; change an\n"
            "issue with luxpm_update_issue, where the change is judged.",
        )
    if name == _UPDATE:
        faults = _update_faults(inp)
        if not faults:
            return 0
        return _deny(
            "\n".join(faults),
            "Moving a closed issue back to open work files it again, and so does writing the\n"
            "work into another issue. An escalation's description (its Verify block) passes.",
        )
    own = repo_project(tree_dir()).upper()
    if _escalation(inp, own) or _handoff(
        inp, own, str(ev.get("transcript_path") or "")
    ):
        return 0
    started, not_now = _started_now(inp, own)
    if started:
        return 0
    title = str(inp.get("title") or inp.get("text") or "")
    return _deny(f"You are about to file: {title[:120]!r}", not_now)


if __name__ == "__main__":
    sys.exit(main())
